{
	admin off
	auto_https off
}

:8080 {
	handle /healthz {
		rewrite * /api/version
		reverse_proxy 127.0.0.1:11434 {
			header_up Host {upstream_hostport}
		}
	}

	@authorized header Authorization "Bearer {$API_KEY}"
	handle @authorized {
		reverse_proxy 127.0.0.1:11434 {
			header_up Host {upstream_hostport}
			header_up -Origin
			flush_interval -1
		}
	}

	respond "missing or wrong bearer token" 401
}

